head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.MGS_NO_UPDT = "저장할 수정내용이 없습니다.";
scwin.MSG_NO_COMT = "위원회심사결과 내역이 없습니다. 새로 추가하시겠습니까?";
scwin.fn_GetPar, scwin.fn_SetPar, scwin.strKeyLstBzProcsNo = "", scwin.strKeyIsurCd = "";
scwin.vScrenID = "ULDSTF05110.xml";
scwin.rowIdx;
scwin.userInfo;

scwin.onpageload = function() {
    scwin.userInfo = $c.session.getUserInfo(); 
    scwin.init();
};
scwin.onpageunload = function() {
};
scwin.fn_getUserId = function() {
    return scwin.userInfo.empNo;
};
scwin.fn_searchCode = async function() {
    const codeOptions = [
		{
			code: "COMITE_INVSTG_RSLT_CD",	
			action: "/api/listing/common/code/list-code-value?codeList=COMITE_INVSTG_RSLT_CD",
			firstRow : ["", ""],
            labelColumn: "text",
            valueColumn: "value",
			compID: "cmb_ComiteInvstgRsltCd"  
		}
	];

	await $c.data.setCommonCode(codeOptions);
};
scwin.fn_searchReqInf = async function() {
    let reqMap = {
        bzProcsNo: dlt_Cmt.getCellData(dlt_Cmt.getRowPosition(), "bzProcsNo")
    };
    const sbmOptions = {
        id: "sbm_prelisting-kindstk-comite-select-info",
        action: "/api/listing/lstproc/kind/prelisting-kindstk-comite/select-info",
        method: "get",
        target: "dma_ReqInf=body",
        isProcessMsg: false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);
    if (res.responseJSON.success) {

    }
};
scwin.fn_search = async function() {
    // 발행기관코드가 키값이다.

    let reqMap = {
        isurCd: scwin.strKeyIsurCd
    };
    const sbmOptions = {
        id: "sbm_prelisting-kindstk-comite",
        action: "/api/listing/lstproc/kind/prelisting-kindstk-comite/select-list",
        method: "get",
        target: "dlt_Cmt=body",
        isProcessMsg: false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);
    if (res.responseJSON.success) {
        if (dlt_Cmt.getRowCount() > 0) {

            for(var i=0; i<dlt_Cmt.getRowCount(); i++) {
                dlt_Cmt.setCellData(i, "jobType", "3");
            }

            scwin.fn_setKeyCtrOnUpd(); // 조회직후에는 수정상태
            grd.setFocusedCell(0, 0, true);
            scwin.fn_searchReqInf();
        } else {
            if (await $c.win.confirm(scwin.MSG_NO_COMT)) {
                scwin.fn_addNewCmt();
            } else {
                await $c.win.closePopup(); // CloseFrame은 호출자가 있을경우 유효하다.

            }
        }
    }
};
scwin.fn_save = async function(jobType) {
    if (scwin.userInfo.depCd.substring(0, 2) !== '25') {
        //유가 심사팀

        //alert("해당 부서만 접수가 가능합니다."); return;

    }

    //위원회일/철회일 필수 체크
    //1줄만 있을 경우, 삭제할 수 없음
    if (med_ComiteDd.getValue() == "") {
        $c.win.alert("위원회일/철회일을 입력하여 주세요");
        med_ComiteDd.focus();
        return false;
    }

    if(jobType == "D"){
        dlt_Cmt.deleteRow(dlt_Cmt.getRowPosition());
    }  

    let vScrenProcTpCd;
    if (jobType == "I") {
        vScrenProcTpCd = "02";//$c.stf.glb.SCREN_PROCS_TP_CD_02;
    } else if (jobType == "U") {
        vScrenProcTpCd = "03";//$c.stf.glb.SCREN_PROCS_TP_CD_03;
    } else if (jobType == "D") {
        vScrenProcTpCd = "04";//$c.stf.glb.SCREN_PROCS_TP_CD_04;
    }
    if ($c.cp.isModified(dlt_Cmt) || $c.cp.isModified(dma_ReqInf)) {
        if(jobType == "D") {
            dlt_Cmt.setCellData(scwin.rowIdx, "jobType", Number(vScrenProcTpCd));
        }
        dma_ReqInf.set("lstComiteRsltSaveEmpNo", scwin.fn_getUserId());

        const sbmOptions = {
            id: "sbm_prelisting-kindstk-comite",
            action: "/api/listing/lstproc/kind/prelisting-kindstk-comite/save" ,
            mediatype: "application/json",
            method: "post",
            ref: 'data:json,[{"id":"dlt_Cmt","key":"copmiteDlrltDto"}]',
            target: "data:json",
            isProcessMsg: false
        };
        const res = await $c.sbm.executeDynamic(sbmOptions);

        if (res.responseJSON.success) {
            if(res.responseJSON.body.result == "S"){
                await $c.win.alert(scwin.MSG_TR_DOME);
                await scwin.fn_search();

                //상장위원회일, 심사구분 reLoad
                let parentWin = $c.win.getParent();
                parentWin.scwin.fn_read_sync();
            }else{
            $c.win.alert(scwin.MSG_TR_FAIL);   
            }
        }else{
            $c.win.alert(scwin.MSG_TR_FAIL);
        }
    } else {
        $c.win.alert(scwin.MGS_NO_UPDT);
    }
};
scwin.fn_addNewCmt = function() {
    dlt_Cmt.insertRow();
    dlt_Cmt.setCellData(dlt_Cmt.getRowCount()-1, "bzProcsNo", scwin.strKeyLstBzProcsNo);
    dlt_Cmt.setCellData(dlt_Cmt.getRowCount()-1, "jobType", "2");
    dlt_Cmt.setRowPosition(dlt_Cmt.getRowCount()-1);
    scwin.rowIdx = dlt_Cmt.getRowPosition();
    grd.setFocusedCell(scwin.rowIdx, scwin.rowIdx, true);
    scwin.fn_searchReqInf();
    scwin.fn_setKeyCtrOnAdd(); // 추가상태에서는  key컬럼수정가능

};
scwin.fn_DeleteRow = function() {
    scwin.fn_save("D");
};
scwin.fn_setKeyCtrOnAdd = function() {
    med_ComiteDd.setReadOnly(false);
};
scwin.fn_setKeyCtrOnUpd = function() {
    med_ComiteDd.setReadOnly(true);
};
scwin.btn_Close_onclick = async function() {
    await $c.win.closePopup();
};
scwin.img_Save_onclick = function() {
    scwin.rowIdx = dlt_Cmt.getRowPosition();
    scwin.fn_save("I");
};
scwin.img_Regist_onclick = function() {
    scwin.fn_addNewCmt();
};
scwin.img_Delete_onclick = function() {
    scwin.rowIdx = dlt_Cmt.getRowPosition();
    scwin.fn_DeleteRow();
};
scwin.init = async function() {
    let arr = new Array();
    await scwin.fn_searchCode();
    scwin.fn_GetPar = $c.win.getParent().scwin.fn_GetPar;
    scwin.fn_SetPar = $c.win.getParent().scwin.fn_SetPar;
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arr);
    }
    txb_IsurCd.setValue((arr.length >= 1 ? arr[0] : ""));
    scwin.strKeyIsurCd = (arr.length >= 1 ? arr[0] : "");
    scwin.strKeyLstBzProcsNo = (arr.length >= 2 ? arr[1] : "");
    txb_CoNm.setValue((arr.length >= 3 ? arr[2] : "")); // 발행기관명도 넘겨받아 컨트롤에 반영해야 한다.

    if (arr.length > 2) {
        scwin.fn_search();
    }
};

scwin.grd_oncellclick = function (rowIndex, columnIndex, columnId) {
	if (dlt_Cmt.getTotalRow() > 0) {
        if (dlt_Cmt.getCellData(rowIndex, "bzProcsNo") != "") {
            scwin.fn_searchReqInf();
        }
    }
};

scwin.dateFormat = function (data) {
    return $c.date.formatDateTime(data, 'yyyy-MM-dd HH:mm:ss');
};
